  ;(function(){var X={"en": {"온라인 • 오프라인 종합 문서 편집기": "Online • Offline all-in-one document editor"}, "ja": {"온라인 • 오프라인 종합 문서 편집기": "オンライン • オフライン対応の総合文書エディター"}, "zh": {"온라인 • 오프라인 종합 문서 편집기": "在线 • 离线一站式文档编辑器"}};for(var l in X){D[l]=D[l]||{};for(var k in X[l])D[l][k]=X[l][k];}})();
  ;(function(){var X={"en": {"열고, 고치고, 함께 편집하세요.": "Open it, edit it, edit together.", "인터넷이 끊겨도 작업은 이어집니다.": "Your work keeps going, even offline.", "더 알아보기": "Learn more"}, "ja": {"열고, 고치고, 함께 편집하세요.": "開いて、直して、一緒に編集。", "인터넷이 끊겨도 작업은 이어집니다.": "ネットが切れても作業は続きます。", "더 알아보기": "詳しく見る"}, "zh": {"열고, 고치고, 함께 편집하세요.": "打开、修改、一起编辑。", "인터넷이 끊겨도 작업은 이어집니다.": "断网也能继续工作。", "더 알아보기": "了解更多"}};for(var l in X){D[l]=D[l]||{};for(var k in X[l])D[l][k]=X[l][k];}})();
  ;(function(){var X={"en": {"어디서나": "Anywhere", "온라인 · 오프라인 어디서나 쓰는 종합 문서 편집기": "An all-in-one document editor that works online and offline", "PDF · PPTX · HWP · DOCX를 설치 없이 열어 고치고, 친구와 실시간으로 함께 편집하고, 원하는 형식으로 내보내세요.": "Open and edit PDF, PPTX, HWP and DOCX without installing anything, co-edit with friends in real time, and export to the format you need.", "어떻게 오프라인에서도 되나요?": "How does it work offline?", "오프라인에서도 작업": "Works offline", "설치 · 가입 없이 시작": "No install, no sign-up", "실시간 공유작업": "Real-time collaboration", "파일은 내 기기에서 처리": "Files stay on your device", "Meow-PDF — 함께 편집하는 화면": "Meow-PDF — editing together", "인터넷이 끊겨도, 휴대폰에서도": "Offline or on your phone,", "작업은 그대로 이어집니다": "your work keeps going", "Meow-PDF는 브라우저 안에서 돌아가는 문서 편집기입니다. 문서는 서버로 보내지 않고 내 기기에서 열고 고치고 저장합니다.": "Meow-PDF is a document editor that runs inside your browser. Documents are opened, edited and saved on your device — never uploaded to a server.", "온라인일 때": "When online", "로그인, 실시간 공유작업과 채팅, 친구 · 메일 · 알림, 페이지 번역처럼 연결이 필요한 기능까지 모두 씁니다.": "Use everything, including features that need a connection: sign-in, real-time collaboration and chat, friends, mail and notifications, and page translation.", "오프라인일 때": "When offline", "한 번 열어 둔 편집기는 연결 없이도 열립니다. 파일 열기, 글자 수정, 그리기, 페이지 정리, PDF · MPDF 저장은 그대로 됩니다.": "Once you've opened the editor, it opens without a connection too. Opening files, editing text, drawing, organizing pages and saving PDF/MPDF all keep working.", "휴대폰 · 태블릿에서": "On phones and tablets", "컴퓨터와 같은 편집기가 작은 화면에 맞춰 바뀝니다. 손가락으로 확대하고 넘기고, 펜으로 바로 표시합니다.": "The same editor adapts to small screens. Pinch to zoom, swipe to turn pages, and mark up right away with a pen.", "문서 작업에 필요한 모든 것을 한곳에": "Everything you need for documents, in one place", "PDF 편집부터 공동 작업, 형식 변환까지. 여러 프로그램을 오가지 않아도 됩니다.": "From PDF editing to collaboration and format conversion — no more switching between apps.", "PDF 안의 글자를 눌러 원래 글꼴 · 크기 · 띄어쓰기 그대로 고칩니다. 스캔본이나 이미지 속 글자도 디지털화로 고칠 수 있는 글자로 바꿉니다.": "Click text in a PDF and edit it with the original font, size and spacing. Digitize turns text in scans and images into editable text, too.", "고유 코드나 링크 하나로 여러 사람이 같은 문서를 함께 고칩니다. 서로의 마우스 위치와 보고 있는 페이지가 프로필 사진으로 보이고, 채팅으로 바로 이야기합니다.": "Share one code or link and edit the same document together. Everyone's cursor and current page show up as profile pictures, and you can talk in chat.", "오프라인에서도": "Offline, too", "한 번 열어 둔 편집기는 인터넷이 끊겨도 그대로 열립니다. 파일 열기 · 편집 · 저장은 모두 내 기기 안에서 처리되어 비행기 · 지하철에서도 작업을 이어갑니다.": "Once opened, the editor opens even when you're offline. Opening, editing and saving all happen on your device, so you can keep working on a plane or the subway.", "그리기 · 도형 · 표": "Drawing, shapes and tables", "펜, 형광펜, 직선, 화살표, 도형, 표, 이미지, 메모, 음성 녹음까지. 형광펜은 글자를 가리지 않고 글줄에 맞춰 칠해지고, 표는 칸마다 정렬과 글자 크기를 정합니다.": "Pen, highlighter, lines, arrows, shapes, tables, images, sticky notes and voice recordings. The highlighter snaps to text lines without hiding them, and each table cell can have its own alignment and font size.", "여러 문서를 탭으로 열고, 전체 페이지 관리에서 회전 · 순서 · 그룹을 정리하고, PDF를 합치고, 용량을 줄입니다.": "Open documents in tabs, rotate, reorder and group pages in the page manager, merge PDFs and reduce file size.", "원하는 형식으로": "Any format you need", "PDF와 편집 상태를 그대로 담는 MPDF로 저장하고, PPTX · Word(.docx) · 한글(.hwpx) · PNG로 내보냅니다.": "Save as PDF or MPDF (keeps your edits editable), and export to PPTX, Word (.docx), Hangul (.hwpx) or PNG.", "문서를 보면서 옆 패널에서 다른 파일, 웹페이지, 계산기, 번역 · 사전, 노트를 함께 엽니다.": "While viewing a document, open other files, web pages, a calculator, translation/dictionary and notes in the side panel.", "친구 · 메일 · 알림": "Friends, mail and notifications", "아이디로 친구를 추가하고 메일을 주고받습니다. 친구가 진행 중인 공유작업에 바로 참여할 수 있습니다.": "Add friends by ID and exchange mail. Jump straight into a shared project a friend is working on.", "영역을 사각형이나 자유 형태로 지정해 그림과 도형의 일부를 오리고 옮깁니다. 자동 레이어와 그림판식 수동 레이어를 고를 수 있습니다.": "Select a rectangle or freeform region to cut and move parts of drawings and shapes. Choose automatic layers or manual, Paint-style layers.", "전체 화면으로 발표하며 펜과 형광펜으로 표시하고, 레이저 포인터는 지나간 자리에 잔상을 남깁니다.": "Present in full screen, mark up with pen and highlighter, and use a laser pointer that leaves a trail.", "내 방식대로": "Your way", "테마 스토어에서 분위기를 바꾸고, 단축키와 도구 모음 위치를 정하고, 39가지 글꼴 중에서 고릅니다. 개발자 콘솔로 명령어 한 줄에 조작할 수도 있습니다.": "Change the look in the theme store, set shortcuts and toolbar position, and pick from 39 fonts. Or control everything with one-line commands in the developer console.", "휴대폰 · 태블릿": "Phones and tablets", "작은 화면에서는 모바일 화면으로 바뀝니다. 아이콘 탭 옵션바, 원형 바로가기 버튼, 오른쪽 작업 패널로 손가락 하나로도 편합니다.": "On small screens it switches to a mobile layout — an icon-tab option bar, a round shortcut button and a slide-out side panel make one-finger use easy.", "PDF · PPTX · HWP · DOCX · 이미지를 끌어다 놓거나 열기를 눌러 선택합니다. 빈 문서로 시작할 수도 있습니다.": "Drag in a PDF, PPTX, HWP, DOCX or image, or click Open. You can also start with a blank document.", "편집 · 함께 작업": "Edit and collaborate", "글자를 고치고, 그리고, 표와 이미지를 넣습니다. 프로젝트 관리 버튼으로 코드나 링크를 보내 함께 고칠 수도 있습니다.": "Edit text, draw, and add tables and images. Send a code or link from the Project button to edit together.", "저장 · 내보내기": "Save and export", "PDF나 MPDF로 저장하고, PPTX · Word · 한글 · PNG로 내보냅니다. 인쇄와 발표 모드도 바로 쓸 수 있습니다.": "Save as PDF or MPDF and export to PPTX, Word, Hangul or PNG. Printing and presentation mode are right there too.", "글자 수정, 그리기, 도형, 이미지": "Text editing, drawing, shapes, images", "PDF · MPDF 저장, 인쇄, 발표 모드": "PDF/MPDF saving, printing, presentation mode", "오프라인 작업, 여러 문서 탭, 알림": "Offline work, multiple tabs, notifications", "공유작업에 참여하기": "Joining shared projects", "공유작업 만들기 · 관리, 친구 · 메일, 프리미엄 글꼴 · 테마": "Creating and managing shared projects, friends & mail, premium fonts & themes", "파일 압축, 표 삽입, 전체 페이지 디지털화, 메모": "File compression, tables, full-document digitizing, sticky notes", "설치도 가입도 필요 없습니다. 한 번 열어 두면 인터넷이 끊겨도, 휴대폰에서도 작업을 이어갈 수 있습니다.": "No install, no sign-up. Open it once and keep working even offline or on your phone.", "공유작업 만들기 · 관리(참여는 무료), 친구 · 메일, PDF 압축, PPTX 내보내기, 음성 녹음 및 MP3 내보내기, 메모, 표 삽입, 전체 페이지 디지털화, 멀티작업(계산기 · 번역 · 사전), 페이지 번역, 개발자 콘솔, 프리미엄 글꼴 · 테마": "Creating and managing shared projects (joining is free), friends & mail, PDF compression, PPTX export, voice recording and MP3 export, sticky notes, tables, full-document digitizing, multitasking (calculator, translation, dictionary), page translation, developer console, premium fonts & themes", "PDF · PPTX · HWP · DOCX를 설치 없이 열어 고치고, 친구와 실시간으로 함께 편집하고, 원하는 형식으로 내보내세요. 한 번 열면 인터넷이 끊겨도 계속 작업할 수 있는 종합 문서 편집기입니다.": "Open and edit PDF, PPTX, HWP and DOCX without installing, co-edit with friends in real time, and export to any format. An all-in-one document editor that keeps working even offline once opened.", "특징": "Highlights", "Meow-PDF — 온라인 · 오프라인 어디서나 쓰는 종합 문서 편집기": "Meow-PDF — An all-in-one document editor that works online and offline"}, "ja": {"어디서나": "どこでも", "온라인 · 오프라인 어디서나 쓰는 종합 문서 편집기": "オンラインでもオフラインでも使えるオールインワン文書エディター", "PDF · PPTX · HWP · DOCX를 설치 없이 열어 고치고, 친구와 실시간으로 함께 편집하고, 원하는 형식으로 내보내세요.": "PDF・PPTX・HWP・DOCXをインストールなしで開いて編集し、友だちとリアルタイムで共同編集して、好きな形式で書き出しましょう。", "어떻게 오프라인에서도 되나요?": "オフラインでも使える仕組み", "오프라인에서도 작업": "オフラインでも作業", "설치 · 가입 없이 시작": "インストール・登録不要", "실시간 공유작업": "リアルタイム共同作業", "파일은 내 기기에서 처리": "ファイルは端末内で処理", "Meow-PDF — 함께 편집하는 화면": "Meow-PDF — 共同編集画面", "인터넷이 끊겨도, 휴대폰에서도": "ネットが切れても、スマホでも", "작업은 그대로 이어집니다": "作業はそのまま続きます", "Meow-PDF는 브라우저 안에서 돌아가는 문서 편집기입니다. 문서는 서버로 보내지 않고 내 기기에서 열고 고치고 저장합니다.": "Meow-PDFはブラウザの中で動く文書エディターです。文書をサーバーに送らず、端末の中で開いて編集・保存します。", "온라인일 때": "オンラインのとき", "로그인, 실시간 공유작업과 채팅, 친구 · 메일 · 알림, 페이지 번역처럼 연결이 필요한 기능까지 모두 씁니다.": "ログイン、リアルタイム共同作業とチャット、友だち・メール・通知、ページ翻訳など、接続が必要な機能まですべて使えます。", "오프라인일 때": "オフラインのとき", "한 번 열어 둔 편집기는 연결 없이도 열립니다. 파일 열기, 글자 수정, 그리기, 페이지 정리, PDF · MPDF 저장은 그대로 됩니다.": "一度開いたエディターは接続なしでも開きます。ファイルを開く、文字の修正、描画、ページ整理、PDF・MPDF保存はそのまま使えます。", "휴대폰 · 태블릿에서": "スマホ・タブレットで", "컴퓨터와 같은 편집기가 작은 화면에 맞춰 바뀝니다. 손가락으로 확대하고 넘기고, 펜으로 바로 표시합니다.": "パソコンと同じエディターが小さな画面に合わせて変わります。指で拡大・ページ送りし、ペンですぐ書き込めます。", "문서 작업에 필요한 모든 것을 한곳에": "文書作業に必要なすべてを一か所に", "PDF 편집부터 공동 작업, 형식 변환까지. 여러 프로그램을 오가지 않아도 됩니다.": "PDF編集から共同作業、形式変換まで。複数のアプリを行き来する必要はありません。", "PDF 안의 글자를 눌러 원래 글꼴 · 크기 · 띄어쓰기 그대로 고칩니다. 스캔본이나 이미지 속 글자도 디지털화로 고칠 수 있는 글자로 바꿉니다.": "PDFの文字を押して、元のフォント・サイズ・間隔のまま修正します。スキャンや画像の文字もデジタル化で編集できる文字に変えます。", "고유 코드나 링크 하나로 여러 사람이 같은 문서를 함께 고칩니다. 서로의 마우스 위치와 보고 있는 페이지가 프로필 사진으로 보이고, 채팅으로 바로 이야기합니다.": "固有コードやリンク一つで、複数人が同じ文書を一緒に編集します。互いのカーソル位置と見ているページがプロフィール写真で表示され、チャットですぐ話せます。", "오프라인에서도": "オフラインでも", "한 번 열어 둔 편집기는 인터넷이 끊겨도 그대로 열립니다. 파일 열기 · 편집 · 저장은 모두 내 기기 안에서 처리되어 비행기 · 지하철에서도 작업을 이어갑니다.": "一度開いたエディターはネットが切れてもそのまま開きます。開く・編集・保存はすべて端末内で処理されるので、飛行機や地下鉄でも作業を続けられます。", "그리기 · 도형 · 표": "描画・図形・表", "펜, 형광펜, 직선, 화살표, 도형, 표, 이미지, 메모, 음성 녹음까지. 형광펜은 글자를 가리지 않고 글줄에 맞춰 칠해지고, 표는 칸마다 정렬과 글자 크기를 정합니다.": "ペン、蛍光ペン、直線、矢印、図形、表、画像、メモ、音声録音まで。蛍光ペンは文字を隠さず行に合わせて塗られ、表はセルごとに配置と文字サイズを設定できます。", "여러 문서를 탭으로 열고, 전체 페이지 관리에서 회전 · 순서 · 그룹을 정리하고, PDF를 합치고, 용량을 줄입니다.": "複数の文書をタブで開き、全ページ管理で回転・順序・グループを整理し、PDFを結合して容量を減らします。", "원하는 형식으로": "好きな形式で", "PDF와 편집 상태를 그대로 담는 MPDF로 저장하고, PPTX · Word(.docx) · 한글(.hwpx) · PNG로 내보냅니다.": "PDFと編集状態をそのまま保つMPDFで保存し、PPTX・Word(.docx)・ハングル(.hwpx)・PNGに書き出します。", "문서를 보면서 옆 패널에서 다른 파일, 웹페이지, 계산기, 번역 · 사전, 노트를 함께 엽니다.": "文書を見ながら、横のパネルで別のファイル、Webページ、電卓、翻訳・辞書、ノートを一緒に開けます。", "친구 · 메일 · 알림": "友だち・メール・通知", "아이디로 친구를 추가하고 메일을 주고받습니다. 친구가 진행 중인 공유작업에 바로 참여할 수 있습니다.": "IDで友だちを追加してメールをやり取りします。友だちが進行中の共同作業にすぐ参加できます。", "영역을 사각형이나 자유 형태로 지정해 그림과 도형의 일부를 오리고 옮깁니다. 자동 레이어와 그림판식 수동 레이어를 고를 수 있습니다.": "四角形や自由な形で範囲を指定し、描画や図形の一部を切り取って移動します。自動レイヤーとペイント風の手動レイヤーを選べます。", "전체 화면으로 발표하며 펜과 형광펜으로 표시하고, 레이저 포인터는 지나간 자리에 잔상을 남깁니다.": "全画面で発表しながらペンと蛍光ペンで書き込み、レーザーポインターは通った跡に残像を残します。", "내 방식대로": "自分好みに", "테마 스토어에서 분위기를 바꾸고, 단축키와 도구 모음 위치를 정하고, 39가지 글꼴 중에서 고릅니다. 개발자 콘솔로 명령어 한 줄에 조작할 수도 있습니다.": "テーマストアで雰囲気を変え、ショートカットとツールバーの位置を決め、39種類のフォントから選べます。開発者コンソールでコマンド一行で操作することもできます。", "휴대폰 · 태블릿": "スマホ・タブレット", "작은 화면에서는 모바일 화면으로 바뀝니다. 아이콘 탭 옵션바, 원형 바로가기 버튼, 오른쪽 작업 패널로 손가락 하나로도 편합니다.": "小さな画面ではモバイル画面に切り替わります。アイコンタブのオプションバー、丸いショートカットボタン、右の作業パネルで指一本でも快適です。", "PDF · PPTX · HWP · DOCX · 이미지를 끌어다 놓거나 열기를 눌러 선택합니다. 빈 문서로 시작할 수도 있습니다.": "PDF・PPTX・HWP・DOCX・画像をドラッグするか、開くを押して選びます。白紙から始めることもできます。", "편집 · 함께 작업": "編集・共同作業", "글자를 고치고, 그리고, 표와 이미지를 넣습니다. 프로젝트 관리 버튼으로 코드나 링크를 보내 함께 고칠 수도 있습니다.": "文字を修正し、描いて、表や画像を入れます。プロジェクト管理ボタンでコードやリンクを送り、一緒に編集することもできます。", "저장 · 내보내기": "保存・書き出し", "PDF나 MPDF로 저장하고, PPTX · Word · 한글 · PNG로 내보냅니다. 인쇄와 발표 모드도 바로 쓸 수 있습니다.": "PDFやMPDFで保存し、PPTX・Word・ハングル・PNGに書き出します。印刷と発表モードもすぐ使えます。", "글자 수정, 그리기, 도형, 이미지": "文字修正、描画、図形、画像", "PDF · MPDF 저장, 인쇄, 발표 모드": "PDF・MPDF保存、印刷、発表モード", "오프라인 작업, 여러 문서 탭, 알림": "オフライン作業、複数タブ、通知", "공유작업에 참여하기": "共同作業への参加", "공유작업 만들기 · 관리, 친구 · 메일, 프리미엄 글꼴 · 테마": "共同作業の作成・管理、友だち・メール、プレミアムフォント・テーマ", "파일 압축, 표 삽입, 전체 페이지 디지털화, 메모": "ファイル圧縮、表の挿入、全ページのデジタル化、メモ", "설치도 가입도 필요 없습니다. 한 번 열어 두면 인터넷이 끊겨도, 휴대폰에서도 작업을 이어갈 수 있습니다.": "インストールも登録も不要です。一度開いておけば、ネットが切れてもスマホでも作業を続けられます。", "공유작업 만들기 · 관리(참여는 무료), 친구 · 메일, PDF 압축, PPTX 내보내기, 음성 녹음 및 MP3 내보내기, 메모, 표 삽입, 전체 페이지 디지털화, 멀티작업(계산기 · 번역 · 사전), 페이지 번역, 개발자 콘솔, 프리미엄 글꼴 · 테마": "共同作業の作成・管理(参加は無料)、友だち・メール、PDF圧縮、PPTX書き出し、音声録音とMP3書き出し、メモ、表の挿入、全ページのデジタル化、マルチ作業(電卓・翻訳・辞書)、ページ翻訳、開発者コンソール、プレミアムフォント・テーマ", "PDF · PPTX · HWP · DOCX를 설치 없이 열어 고치고, 친구와 실시간으로 함께 편집하고, 원하는 형식으로 내보내세요. 한 번 열면 인터넷이 끊겨도 계속 작업할 수 있는 종합 문서 편집기입니다.": "PDF・PPTX・HWP・DOCXをインストールなしで開いて編集し、友だちとリアルタイムで共同編集し、好きな形式で書き出せます。一度開けばネットが切れても作業を続けられるオールインワン文書エディターです。", "특징": "特徴", "Meow-PDF — 온라인 · 오프라인 어디서나 쓰는 종합 문서 편집기": "Meow-PDF — オンラインでもオフラインでも使えるオールインワン文書エディター"}, "zh": {"어디서나": "随时随地", "온라인 · 오프라인 어디서나 쓰는 종합 문서 편집기": "在线离线都能用的一站式文档编辑器", "PDF · PPTX · HWP · DOCX를 설치 없이 열어 고치고, 친구와 실시간으로 함께 편집하고, 원하는 형식으로 내보내세요.": "无需安装即可打开并编辑 PDF · PPTX · HWP · DOCX，与好友实时协同编辑，并导出为所需格式。", "어떻게 오프라인에서도 되나요?": "离线也能用？", "오프라인에서도 작업": "离线也能工作", "설치 · 가입 없이 시작": "无需安装 · 注册", "실시간 공유작업": "实时共享协作", "파일은 내 기기에서 처리": "文件在本机处理", "Meow-PDF — 함께 편집하는 화면": "Meow-PDF — 协同编辑界面", "인터넷이 끊겨도, 휴대폰에서도": "断网也好，用手机也罢，", "작업은 그대로 이어집니다": "工作照常继续", "Meow-PDF는 브라우저 안에서 돌아가는 문서 편집기입니다. 문서는 서버로 보내지 않고 내 기기에서 열고 고치고 저장합니다.": "Meow-PDF 是在浏览器中运行的文档编辑器。文档不会上传到服务器，而是在本机打开、编辑和保存。", "온라인일 때": "在线时", "로그인, 실시간 공유작업과 채팅, 친구 · 메일 · 알림, 페이지 번역처럼 연결이 필요한 기능까지 모두 씁니다.": "登录、实时协作与聊天、好友 · 邮件 · 通知、页面翻译等需要联网的功能全部可用。", "오프라인일 때": "离线时", "한 번 열어 둔 편집기는 연결 없이도 열립니다. 파일 열기, 글자 수정, 그리기, 페이지 정리, PDF · MPDF 저장은 그대로 됩니다.": "打开过一次的编辑器无需联网也能打开。打开文件、修改文字、绘图、整理页面、保存 PDF · MPDF 都照常可用。", "휴대폰 · 태블릿에서": "在手机 · 平板上", "컴퓨터와 같은 편집기가 작은 화면에 맞춰 바뀝니다. 손가락으로 확대하고 넘기고, 펜으로 바로 표시합니다.": "与电脑相同的编辑器会自动适配小屏幕。手指缩放、翻页，用笔直接标注。", "문서 작업에 필요한 모든 것을 한곳에": "文档工作所需的一切，尽在一处", "PDF 편집부터 공동 작업, 형식 변환까지. 여러 프로그램을 오가지 않아도 됩니다.": "从 PDF 编辑到协作、格式转换，无需在多个程序间切换。", "PDF 안의 글자를 눌러 원래 글꼴 · 크기 · 띄어쓰기 그대로 고칩니다. 스캔본이나 이미지 속 글자도 디지털화로 고칠 수 있는 글자로 바꿉니다.": "点击 PDF 中的文字，保持原字体 · 字号 · 间距直接修改。扫描件或图片中的文字也能通过数字化变成可编辑文字。", "고유 코드나 링크 하나로 여러 사람이 같은 문서를 함께 고칩니다. 서로의 마우스 위치와 보고 있는 페이지가 프로필 사진으로 보이고, 채팅으로 바로 이야기합니다.": "一个专属代码或链接，多人即可共同编辑同一文档。彼此的鼠标位置和正在查看的页面以头像显示，还能直接聊天。", "오프라인에서도": "离线也可用", "한 번 열어 둔 편집기는 인터넷이 끊겨도 그대로 열립니다. 파일 열기 · 편집 · 저장은 모두 내 기기 안에서 처리되어 비행기 · 지하철에서도 작업을 이어갑니다.": "打开过的编辑器即使断网也能打开。打开 · 编辑 · 保存都在本机完成，在飞机、地铁上也能继续工作。", "그리기 · 도형 · 표": "绘图 · 形状 · 表格", "펜, 형광펜, 직선, 화살표, 도형, 표, 이미지, 메모, 음성 녹음까지. 형광펜은 글자를 가리지 않고 글줄에 맞춰 칠해지고, 표는 칸마다 정렬과 글자 크기를 정합니다.": "钢笔、荧光笔、直线、箭头、形状、表格、图片、便签、录音一应俱全。荧光笔贴合文字行而不遮挡，表格可逐格设置对齐和字号。", "여러 문서를 탭으로 열고, 전체 페이지 관리에서 회전 · 순서 · 그룹을 정리하고, PDF를 합치고, 용량을 줄입니다.": "用标签页打开多个文档，在全部页面管理中整理旋转 · 顺序 · 分组，合并 PDF 并压缩体积。", "원하는 형식으로": "导出所需格式", "PDF와 편집 상태를 그대로 담는 MPDF로 저장하고, PPTX · Word(.docx) · 한글(.hwpx) · PNG로 내보냅니다.": "保存为 PDF 或保留编辑状态的 MPDF，并可导出为 PPTX · Word(.docx) · 韩文(.hwpx) · PNG。", "문서를 보면서 옆 패널에서 다른 파일, 웹페이지, 계산기, 번역 · 사전, 노트를 함께 엽니다.": "查看文档的同时，在侧边面板打开其他文件、网页、计算器、翻译 · 词典和笔记。", "친구 · 메일 · 알림": "好友 · 邮件 · 通知", "아이디로 친구를 추가하고 메일을 주고받습니다. 친구가 진행 중인 공유작업에 바로 참여할 수 있습니다.": "通过 ID 添加好友并收发邮件，可直接加入好友正在进行的共享协作。", "영역을 사각형이나 자유 형태로 지정해 그림과 도형의 일부를 오리고 옮깁니다. 자동 레이어와 그림판식 수동 레이어를 고를 수 있습니다.": "用矩形或自由形状选区，裁剪并移动绘图和形状的一部分。可选择自动图层或画图式手动图层。", "전체 화면으로 발표하며 펜과 형광펜으로 표시하고, 레이저 포인터는 지나간 자리에 잔상을 남깁니다.": "全屏演示时可用钢笔和荧光笔标注，激光笔会留下拖尾。", "내 방식대로": "随心定制", "테마 스토어에서 분위기를 바꾸고, 단축키와 도구 모음 위치를 정하고, 39가지 글꼴 중에서 고릅니다. 개발자 콘솔로 명령어 한 줄에 조작할 수도 있습니다.": "在主题商店切换风格，设置快捷键和工具栏位置，从 39 种字体中挑选。也可在开发者控制台用一行命令操作。", "휴대폰 · 태블릿": "手机 · 平板", "작은 화면에서는 모바일 화면으로 바뀝니다. 아이콘 탭 옵션바, 원형 바로가기 버튼, 오른쪽 작업 패널로 손가락 하나로도 편합니다.": "小屏幕会切换为移动版界面。图标式选项栏、圆形快捷按钮和右侧工作面板，单指操作也很方便。", "PDF · PPTX · HWP · DOCX · 이미지를 끌어다 놓거나 열기를 눌러 선택합니다. 빈 문서로 시작할 수도 있습니다.": "拖入 PDF · PPTX · HWP · DOCX · 图片，或点击打开选择。也可以从空白文档开始。", "편집 · 함께 작업": "编辑 · 协作", "글자를 고치고, 그리고, 표와 이미지를 넣습니다. 프로젝트 관리 버튼으로 코드나 링크를 보내 함께 고칠 수도 있습니다.": "修改文字、绘图、插入表格和图片。还可通过项目管理按钮发送代码或链接一起编辑。", "저장 · 내보내기": "保存 · 导出", "PDF나 MPDF로 저장하고, PPTX · Word · 한글 · PNG로 내보냅니다. 인쇄와 발표 모드도 바로 쓸 수 있습니다.": "保存为 PDF 或 MPDF，导出为 PPTX · Word · 韩文 · PNG。打印和演示模式也可直接使用。", "글자 수정, 그리기, 도형, 이미지": "文字修改、绘图、形状、图片", "PDF · MPDF 저장, 인쇄, 발표 모드": "PDF · MPDF 保存、打印、演示模式", "오프라인 작업, 여러 문서 탭, 알림": "离线工作、多标签页、通知", "공유작업에 참여하기": "加入共享协作", "공유작업 만들기 · 관리, 친구 · 메일, 프리미엄 글꼴 · 테마": "创建 · 管理共享协作、好友 · 邮件、高级字体 · 主题", "파일 압축, 표 삽입, 전체 페이지 디지털화, 메모": "文件压缩、插入表格、全部页面数字化、便签", "설치도 가입도 필요 없습니다. 한 번 열어 두면 인터넷이 끊겨도, 휴대폰에서도 작업을 이어갈 수 있습니다.": "无需安装，也无需注册。打开一次后，断网或在手机上都能继续工作。", "공유작업 만들기 · 관리(참여는 무료), 친구 · 메일, PDF 압축, PPTX 내보내기, 음성 녹음 및 MP3 내보내기, 메모, 표 삽입, 전체 페이지 디지털화, 멀티작업(계산기 · 번역 · 사전), 페이지 번역, 개발자 콘솔, 프리미엄 글꼴 · 테마": "创建 · 管理共享协作（加入免费）、好友 · 邮件、PDF 压缩、PPTX 导出、录音及 MP3 导出、便签、插入表格、全部页面数字化、多任务（计算器 · 翻译 · 词典）、页面翻译、开发者控制台、高级字体 · 主题", "PDF · PPTX · HWP · DOCX를 설치 없이 열어 고치고, 친구와 실시간으로 함께 편집하고, 원하는 형식으로 내보내세요. 한 번 열면 인터넷이 끊겨도 계속 작업할 수 있는 종합 문서 편집기입니다.": "无需安装即可打开编辑 PDF · PPTX · HWP · DOCX，与好友实时协作，并导出为任意格式。打开一次后断网也能继续工作的一站式文档编辑器。", "특징": "特点", "Meow-PDF — 온라인 · 오프라인 어디서나 쓰는 종합 문서 편집기": "Meow-PDF — 在线离线都能用的一站式文档编辑器"}};for(var l in X){D[l]=D[l]||{};for(var k in X[l])D[l][k]=X[l][k];}})();
